6c-7a79df9eb29f" :question/math-academy-id "q-79742"} {:db/id 17592186348269 :question/id #uuid "9de6414e-34ab-5a34-9416-91c09d2f0ef2" :question/math-academy-id "q-79743"} {:db/id 17592186393982 :question/id #uuid "b4cf2d9e-3d03-57db-bef6-4b2ef0739dbd" :question/math-academy-id "q-79955"}] :knowledge-point/title "Computing the Differential of a Multivariable Function"} {:db/id 17592186124374 :question/id #uuid "8ebce398-b228-51b0-8506-e0c6124478a5" :question/math-academy-id "e-6852" :knowledge-point/_canonical-example [{:db/id 17592186124565 :knowledge-point/id #uuid "4f23c5c7-d281-54da-b625-412925c80667" :knowledge-point/title "Computing the Differential of a Multivariable Function"}] :question/problem "Find the differential for $f(x,y) = x^2 \sin y.$" :question/worked-solution "We compute the differential using the formula:

$$
\begin{aligned}\text{d}f(x,y) & =(\frac{∂f}{∂x})\,\text{d}x+(\frac{∂f}{∂y})\,\text{d}y \\  & =(2x\operatorname{sin}⁡y)\,\text{d}x+({x}^{2}\operatorname{cos}⁡y)\,\text{d}y \\  & =2x\operatorname{sin}⁡y\,\text{d}x+{x}^{2}\operatorname{cos}⁡y\,\text{d}y\end{aligned}
$$"} {:db/id 17592186048707} {:db/id 17592186125052 :question/id #uuid "914e7517-17c3-54d3-96ce-3e196608d406" :question/math-academy-id "q-37282" :knowledge-point/_questions [{:db/id 17592186124565 :knowledge-point/id #uuid "4f23c5c7-d281-54da-b625-412925c80667" :knowledge-point/title "Computing the Differential of a Multivariable Function"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "819d161a-21cf-535e-bd37-4754ea1a38e6" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-y\sin ydx - (2z^{2} - x\sin x)dy - 4yzdz" :db/id 17592186122913} {:answer/id #uuid "c9f41994-af80-51f0-a777-c868bf2016f3" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-y\sin (xy)dx - (2z^{2} + x\sin (xy))dy - 4yzdz" :db/id 17592186122914} {:answer/id #uuid "d7ff6632-8a2c-51e3-a5d2-71c9bb45bfda" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-2z^{2} + (x - y)\sin (xy) - 4yz" :db/id 17592186122915} {:answer/id #uuid "12e29271-2a8e-5c55-8816-b4e4343e05c2" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-y\sin xdx - (2z^{2} + x\sin (xy))dy - 4yzdz" :db/id 17592186122916} {:answer/id #uuid "54b1099d-408e-55ce-99c9-f79f1fe7a5c6" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "y\cos (xy)dx + (2z^{2} + x\cos (xy))dy + 4yzdz" :db/id 17592186122917}] :answer-field/id #uuid "c93bb65c-ed80-5778-98ea-e0777c1824a8" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186122912} {:answer-field/choices [{:answer/id #uuid "70c06e4f-a84e-5dc0-95c1-0e840c268a55" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-y\operatorname{sin}⁡y\,\text{d}x-(2{z}^{2}-x\operatorname{sin}⁡x)\,\text{d}y-4yz\,\text{d}z" :db/id 17592186392065} {:answer/id #uuid "36dbb4e2-ae10-5f4c-a999-db7893f4043c" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-2{z}^{2}+(x-y)\operatorname{sin}⁡(xy)-4yz" :db/id 17592186392066} {:answer/id #uuid "aae002db-fce7-56b0-8e0b-e5c176407dde" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-y\operatorname{sin}⁡(xy)\,\text{d}x-(2{z}^{2}+x\operatorname{sin}⁡(xy))\,\text{d}y-4yz\,\text{d}z" :db/id 17592186392067} {:answer/id #uuid "8678ac34-b98c-546c-9b8a-4fa9ad208edc" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-y\operatorname{sin}⁡x\,\text{d}x-(2{z}^{2}+x\operatorname{sin}⁡(xy))\,\text{d}y-4yz\,\text{d}z" :db/id 17592186392068} {:answer/id #uuid "2d245c9d-f758-5b87-b9fd-6a4eb0d73a94" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "y\operatorname{cos}⁡(xy)\,\text{d}x+(2{z}^{2}+x\operatorname{cos}⁡(xy))\,\text{d}y+4yz\,\text{d}z" :db/id 17592186392069}] :answer-field/correct {:answer/id #uuid "aae002db-fce7-56b0-8e0b-e5c176407dde" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-y\operatorname{sin}⁡(xy)\,\text{d}x-(2{z}^{2}+x\operatorname{sin}⁡(xy))\,\text{d}y-4yz\,\text{d}z" :db/id 17592186392067} :answer-field/id #uuid "411881c8-1922-500f-a541-940ee58225d1" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186392064}] :question/difficulty {:db/id 17592186045487 :db/ident :question.difficulty/moderate} :question/problem "Find the differential $\text{d}f$ for the function $f(x,y,z)=\operatorname{cos}⁡(xy)-2{z}^{2}y.$" :question/worked-solution "We compute the differential using the formula:

$$
\begin{aligned}\text{d}f(x,y,z) & =(\frac{∂f}{∂x})\,\text{d}x+(\frac{∂f}{∂y})\,\text{d}y+(\frac{∂f}{∂z})\,\text{d}z \\  & =[-y\operatorname{sin}⁡(xy)]\,\text{d}x+[-2{z}^{2}-x\operatorname{sin}⁡(xy)]\,\text{d}y+[-4yz]\,\text{d}z \\  & =-y\operatorname{sin}⁡(xy)\,\text{d}x-(2{z}^{2}+x\operatorname{sin}⁡(xy))\,\text{d}y-4yz\,\text{d}z\end{aligned}
$$"} {:db/id 17592186125056 :question/id #uuid "3d0cda7b-1864-5320-acd1-fb1c921ad388" :question/math-academy-id "q-37307"} {:db/id 17592186284575 :question/id #uuid "5bb0fc77-ef03-5d09-9484-1c0a41da751d" :question/math-academy-id "q-167153"} {:db/id 17592186348265 :question/id #uuid "af353571-e5f3-5cb8-87db-52892f4fbe38" :question/math-academy-id "q-79739"} {:db/id 17592186348266 :question/id #uuid "08d66e91-862a-530e-b18f-86f79ced0d5f" :question/math-academy-id "q-79740" :knowledge-point/_questions [{:db/id 17592186124565 :knowledge-point/id #uuid "4f23c5c7-d281-54da-b625-412925c80667" :knowledge-point/title "Computing the Differential of a Multivariable Function"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "05905e56-e689-5126-840d-bc1116dd72e7" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4{y}^{3}\,\text{d}x+12{y}^{2}\,\text{d}y" :db/id 17592186345402} {:answer/id #uuid "67caff4a-7e36-5bec-ac58-0c42c8671613" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{\text{d}x}{x}+12{y}^{2}\,\text{d}y" :db/id 17592186346257} {:answer/id #uuid "8cab1644-ef8d-51ab-a9c3-417c7b7e3cf7" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{{y}^{4}\,\text{d}x}{x}+4{y}^{3}\operatorname{ln}⁡x\,\text{d}y" :db/id 17592186346574} {:answer/id #uuid "9a950f20-f785-50c1-a237-5e98fddf7f3a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4{y}^{3}\,\text{d}x+12{y}^{2}\operatorname{ln}⁡x\,\text{d}y" :db/id 17592186346700} {:answer/id #uuid "ac8fc4ec-515e-5142-8b79-f41f0428a75d" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{4{y}^{3}\,\text{d}x}{x}+12{y}^{2}\operatorname{ln}⁡x\,\text{d}y" :db/id 17592186346855}] :answer-field/correct {:answer/id #uuid "ac8fc4ec-515e-5142-8b79-f41f0428a75d" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{4{y}^{3}\,\text{d}x}{x}+