p/id #uuid "896f3d03-adff-53cf-be59-7b4310e8b280" :step/math-academy-id 25517}] :activity/title "Differentials" :activity/type {:db/id 17592186045463 :db/ident :activity.type/lesson} :db/id 17592186124739} {:db/id 17592186125479 :step/content {:db/id 17592186125813 :tutorial/content "The **differential** of a multivariable function $f(x,y)$ is denoted $\textrm df(x,y)$ and represents the infinitesimal change in the function value that occurs when the inputs $x$ and $y$ are changed by infinitesimal amounts $\textrm dx$ and $\textrm dy.$

The formula for the differential comes from the multivariable chain rule, which can be expressed as

$$
\begin{aligned}\text{d}f(x,y) & =(\frac{∂f}{∂x})\,\text{d}x+(\frac{∂f}{∂y})\,\text{d}y.\end{aligned}
$$

Note that the differential can be extended to any number of variables. For example, for a three-variable function $f(x,y,z),$ we have

$$
\begin{aligned}\text{d}f(x,y,z) & =(\frac{∂f}{∂x})\,\text{d}x+(\frac{∂f}{∂y})\,\text{d}y+(\frac{∂f}{∂z})\,\text{d}z.\end{aligned}
$$" :tutorial/id #uuid "549aa462-1d86-5880-b6e2-2f6b1d79b41d" :tutorial/math-academy-id 4191 :tutorial/title "Introduction"} :step/id #uuid "ca5fbd6f-0bec-58b1-a606-32a0d7df8952" :step/math-academy-id 25416 :step/next {:db/id 17592186125477}} {:db/id 17592186125477 :step/content {:db/id 17592186124565 :knowledge-point/canonical-example {:db/id 17592186124374 :question/id #uuid "8ebce398-b228-51b0-8506-e0c6124478a5" :question/math-academy-id "e-6852"} :knowledge-point/id #uuid "4f23c5c7-d281-54da-b625-412925c80667" :knowledge-point/key-prerequisites [{:db/id 17592186048707}] :knowledge-point/questions [{:db/id 17592186125052} {:db/id 17592186125056} {:db/id 17592186284575} {:db/id 17592186348265} {:db/id 17592186348266} {:db/id 17592186348267} {:db/id 17592186348268} {:db/id 17592186348269} {:db/id 17592186393982}] :knowledge-point/title "Computing the Differential of a Multivariable Function"} :step/id #uuid "bf1f5b6c-b40c-5ff9-9ed6-50ee5d23ff70" :step/math-academy-id 25383 :step/next {:db/id 17592186125478}} {:db/id 17592186125478 :step/content {:db/id 17592186124566 :knowledge-point/canonical-example {:db/id 17592186124375 :question/id #uuid "bb3ab0dc-7e26-58f5-a0c2-564c01c77f2e" :question/math-academy-id "e-6854"} :knowledge-point/id #uuid "153739f2-df62-5baf-8438-225edfc33ecb" :knowledge-point/questions [{:db/id 17592186125053} {:db/id 17592186125057} {:db/id 17592186284605} {:db/id 17592186348270} {:db/id 17592186348271} {:db/id 17592186348321} {:db/id 17592186372349} {:db/id 17592186375377} {:db/id 17592186375384} {:db/id 17592186393968}] :knowledge-point/title "Computing a Differential in a Geometrical Context"} :step/id #uuid "34d39ab5-5a0c-5548-9b37-4b9ff25664cc" :step/math-academy-id 25385 :step/next {:db/id 17592186125480}} {:db/id 17592186125480 :step/content {:db/id 17592186125814 :tutorial/content "Given a multivariable function $f(x,y),$ the differential

